-- Run only in a disposable local PostgreSQL database after 001..005. All synthetic records roll back.
BEGIN;
CREATE FUNCTION pg_temp.check_true(value boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; END $$;
CREATE FUNCTION pg_temp.local_file(seed text) RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_build_object('id','ncp-'||md5(seed)||md5(seed),'kind','ncp','ncpVersion','0100','sha256',md5(seed)||md5(seed),'byteLength',52,'storagePath','ncp/'||md5(seed)||md5(seed)||'.ncp','url','https://fixture.invalid/community/'||md5(seed)||'.ncp','originalName','local.NCP'); $$;
DO $$
DECLARE a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); preset uuid; root_comment uuid; reply uuid; msg uuid; ticket uuid:=gen_random_uuid();
 r jsonb; saved jsonb; body jsonb; file jsonb; caught boolean; n integer;
BEGIN
 INSERT INTO nikon_users(id,nickname,created_at) VALUES(a,'local-author',now()-interval '2 days'),(b,'local-replier',now()-interval '2 days');
 file:=jsonb_build_object('id','ncp-'||repeat('a',64),'kind','ncp','ncpVersion','0100','sha256',repeat('a',64),'byteLength',52,'storagePath','ncp/'||repeat('a',64)||'.ncp','url','https://fixture.invalid/community/files/ncp-'||repeat('a',64)||'.ncp','originalName','local.NCP');
 PERFORM nikon_community('addAsset',a,NULL,jsonb_build_object('asset',file));
 body:=jsonb_build_object('name','Local test','description','Plain description','category','Portrait','compatibleModels','[]'::jsonb,'sortOrder',0,'rightsConfirmed',true,'fileAssetId',file->>'id','previewAssetId',NULL,'submit',true,'idempotencyKey','create-local-0001');
 saved:=nikon_community('save',a,NULL,body); preset:=(saved->>'id')::uuid;
 PERFORM pg_temp.check_true(saved->>'status'='pending','submit enters review');
 PERFORM pg_temp.check_true(nikon_community('save',a,NULL,body)=saved,'idempotency returns original result');
 caught:=false; BEGIN PERFORM nikon_community('save',a,NULL,body||'{"name":"Different"}'); EXCEPTION WHEN raise_exception THEN caught:=SQLERRM='IDEMPOTENCY_CONFLICT'; END; PERFORM pg_temp.check_true(caught,'idempotency conflicts');
 PERFORM pg_temp.check_true((nikon_community('feed')->>'total')::integer=0,'pending hidden from feed');
 PERFORM pg_temp.check_true(nikon_community('publicAsset',NULL,NULL,jsonb_build_object('assetId',file->>'id')) IS NULL,'pending asset private');
 caught:=false; BEGIN PERFORM nikon_community('ownDetail',b,preset); EXCEPTION WHEN raise_exception THEN caught:=SQLERRM='NOT_FOUND'; END; PERFORM pg_temp.check_true(caught,'ownership');
 PERFORM nikon_community('adminReviewSubmission',NULL,preset,'{"actor":"local-admin","decision":"approve","expectedRevision":1}');
 PERFORM pg_temp.check_true((nikon_community('feed')->>'total')::integer=1,'approved in feed');
 PERFORM pg_temp.check_true(nikon_community('publicAsset',NULL,NULL,jsonb_build_object('assetId',file->>'id'))=file,'approved asset available');
 r:=nikon_community('save',a,preset,body||'{"name":"Edited","submit":false,"expectedRevision":1,"idempotencyKey":"edit-local-0001"}');
 PERFORM pg_temp.check_true(r->>'status'='draft' AND (r->>'hasUnpublishedChanges')::boolean,'edit re-review draft');
 PERFORM pg_temp.check_true(nikon_community('detail',NULL,preset)->>'name'='Local test','old published revision retained');
 PERFORM nikon_community('adminSetSettings',NULL,NULL,'{"actor":"local-admin","settings":{"commentIntervalSeconds":0}}');
 r:=nikon_community('comment',a,preset,'{"text":"root-body","idempotencyKey":"root-local-0001"}'); root_comment:=(r->>'id')::uuid;
 body:=jsonb_build_object('text','reply-secret','parentId',root_comment,'idempotencyKey','reply-local-0001');
 r:=nikon_community('comment',b,preset,body); reply:=(r->>'id')::uuid;
 PERFORM pg_temp.check_true((nikon_community('comments',NULL,preset,jsonb_build_object('focusCommentId',reply))->>'focusAvailable')::boolean,'message focus includes old reply');
 PERFORM nikon_community('comment',b,preset,body);
 PERFORM pg_temp.check_true((nikon_community('unread',a)->>'unread')::integer=2,'one durable reply and approval notification');
 r:=jsonb_path_query_first(nikon_community('messages',a),'$.items[*] ? (@.type == "reply")'); msg:=(r->>'id')::uuid;
 PERFORM pg_temp.check_true(r->>'text'='reply-secret','message current visible body');
 PERFORM nikon_community('read',b,msg);
 PERFORM pg_temp.check_true((nikon_community('unread',a)->>'unread')::integer=2,'read ownership');
 PERFORM nikon_community('read',a,msg);
 PERFORM pg_temp.check_true((nikon_community('unread',a)->>'unread')::integer=1,'read persisted');
 PERFORM nikon_community('readAll',a);
 PERFORM pg_temp.check_true((nikon_community('unread',a)->>'unread')::integer=0,'all read persisted');
 PERFORM nikon_community('comment',a,preset,jsonb_build_object('text','self','parentId',root_comment,'idempotencyKey','self-local-0001'));
 PERFORM pg_temp.check_true((nikon_community('messages',a)->>'total')::integer=2,'self reply excluded');
 caught:=false; BEGIN PERFORM nikon_community('comment',a,preset,jsonb_build_object('text','third-level','parentId',reply,'idempotencyKey','third-local-0001')); EXCEPTION WHEN raise_exception THEN caught:=SQLERRM='COMMENT_UNAVAILABLE'; END; PERFORM pg_temp.check_true(caught,'only two levels');
 PERFORM nikon_community('report',a,reply,'{"reason":"local report","idempotencyKey":"report-local-0001"}');
 PERFORM pg_temp.check_true((nikon_community('adminReports')->>'total')::integer=1,'report persisted');
 PERFORM nikon_community('adminReviewComment',NULL,reply,'{"actor":"local-admin","decision":"hide","reason":"local hidden"}');
 PERFORM pg_temp.check_true(nikon_community('comment',b,preset,body)->>'text'='','idempotent replay cannot leak hidden body');
 r:=jsonb_path_query_first(nikon_community('messages',a),'$.items[*] ? (@.type == "reply")');
 PERFORM pg_temp.check_true(r->>'text'='' AND NOT (r->>'available')::boolean,'hidden reply never leaks in messages');
 PERFORM pg_temp.check_true(NOT (nikon_community('comments',NULL,preset,jsonb_build_object('focusCommentId',reply))->>'focusAvailable')::boolean,'hidden focus unavailable');
 PERFORM nikon_community('deleteComment',a,root_comment);
 PERFORM pg_temp.check_true(nikon_community('comments',NULL,preset)->'items'->0->>'text'='','deleted body removed');
 PERFORM nikon_community('adminSetRestrictions',NULL,b,jsonb_build_object('actor','local-admin','mutedUntil',now()+interval '1 day','reason','local test'));
 caught:=false; BEGIN PERFORM nikon_community('comment',b,preset,'{"text":"blocked","idempotencyKey":"muted-local-0001"}'); EXCEPTION WHEN raise_exception THEN caught:=SQLERRM='USER_MUTED'; END; PERFORM pg_temp.check_true(caught,'mute enforced transactionally');
 PERFORM nikon_community('adminReviewSubmission',NULL,preset,'{"actor":"local-admin","decision":"withdraw","expectedRevision":2}');
 PERFORM pg_temp.check_true((nikon_community('feed')->>'total')::integer=0,'withdraw removed feed');
 PERFORM pg_temp.check_true(nikon_community('publicAsset',NULL,NULL,jsonb_build_object('assetId',file->>'id')) IS NULL,'withdraw revokes public asset');
 PERFORM pg_temp.check_true((nikon_community('versions',a,preset)->'items'->0->>'revision')::integer=2,'revision history retained');
 PERFORM pg_temp.check_true(nikon_issue_challenge(ticket,repeat('b',64),repeat('c',64),repeat('d',64),now()+interval '2 minutes'),'challenge issued');
 PERFORM pg_temp.check_true(nikon_consume_challenge(ticket,repeat('b',64),repeat('c',64),repeat('d',64),'register'),'challenge valid');
 PERFORM pg_temp.check_true(NOT nikon_consume_challenge(ticket,repeat('b',64),repeat('c',64),repeat('d',64),'register'),'challenge one time');
 ticket:=gen_random_uuid(); PERFORM nikon_issue_challenge(ticket,repeat('b',64),repeat('c',64),repeat('d',64),now()+interval '2 minutes');
 PERFORM pg_temp.check_true(NOT nikon_consume_challenge(ticket,repeat('f',64),repeat('c',64),repeat('d',64),'register'),'challenge wrong answer');
 PERFORM pg_temp.check_true(NOT nikon_consume_challenge(ticket,repeat('b',64),repeat('c',64),repeat('d',64),'register'),'wrong answer consumed ticket');
 FOR n IN 1..8 LOOP r:=to_jsonb(nikon_abuse_allowed('register',repeat('e',64),md5(n::text)||md5(n::text))); END LOOP;
 PERFORM pg_temp.check_true(NOT nikon_abuse_allowed('register',repeat('e',64),repeat('f',64)),'source quota resists rotating installation');
 PERFORM nikon_abuse_allowed('register',repeat('e',64),repeat('f',64)); PERFORM nikon_abuse_allowed('register',repeat('e',64),repeat('f',64));
 PERFORM pg_temp.check_true((SELECT count(*)=1 FROM nikon_community_audit WHERE action='abuse:register' AND target=repeat('e',64)),'risk audit aggregates rejected attempts');
 PERFORM pg_temp.check_true((SELECT (detail->>'blockedCount')::integer=3 FROM nikon_community_audit WHERE action='abuse:register' AND target=repeat('e',64)),'risk audit aggregate count');
 PERFORM pg_temp.check_true(NOT has_table_privilege('anon','nikon_community_messages','SELECT'),'private tables deny anon');
 PERFORM pg_temp.check_true(NOT has_function_privilege('authenticated','nikon_community(text,uuid,uuid,jsonb)','EXECUTE'),'RPC deny client role');
END $$;
DO $$
DECLARE fresh uuid:=gen_random_uuid(); normal uuid:=gen_random_uuid(); commenter uuid:=gen_random_uuid();
 p uuid; file jsonb; body jsonb; result jsonb; caught boolean; i integer; curated uuid:=gen_random_uuid();
BEGIN
 INSERT INTO nikon_users(id,nickname,created_at) VALUES(fresh,'local-new',now()),(normal,'local-normal',now()-interval '2 days'),(commenter,'local-budget',now()-interval '2 days');
 file:=jsonb_build_object('id','ncp-'||repeat('1',64),'kind','ncp','ncpVersion','0100','sha256',repeat('1',64),'byteLength',52,'storagePath','ncp/'||repeat('1',64)||'.ncp','url','https://fixture.invalid/community/file.ncp','originalName','local.NCP');
 PERFORM nikon_community('addAsset',fresh,NULL,jsonb_build_object('asset',file)); PERFORM nikon_community('addAsset',normal,NULL,jsonb_build_object('asset',file));
 body:=jsonb_build_object('name','Local quota','category','','compatibleModels','[]'::jsonb,'rightsConfirmed',true,'fileAssetId',file->>'id','submit',true,'idempotencyKey','fresh-submit-001');
 result:=nikon_community('save',fresh,NULL,body); p:=(result->>'id')::uuid;
 caught:=false; BEGIN PERFORM nikon_community('save',fresh,NULL,body||'{"idempotencyKey":"fresh-duplicate-002"}'); EXCEPTION WHEN raise_exception THEN caught:=SQLERRM='DUPLICATE_SUBMISSION'; END; PERFORM pg_temp.check_true(caught,'same content cannot create another submission with a different key');
 file:=pg_temp.local_file('fresh-second'); PERFORM nikon_community('addAsset',fresh,NULL,jsonb_build_object('asset',file)); body:=body||jsonb_build_object('fileAssetId',file->>'id');
 caught:=false; BEGIN PERFORM nikon_community('save',fresh,NULL,body||'{"idempotencyKey":"fresh-submit-002"}'); EXCEPTION WHEN raise_exception THEN caught:=SQLERRM='SUBMISSION_QUOTA'; END; PERFORM pg_temp.check_true(caught,'new account first day one submission');
 PERFORM nikon_community('adminReviewSubmission',NULL,p,'{"actor":"local-admin","decision":"reject","expectedRevision":1,"reason":"local reason"}');
 PERFORM pg_temp.check_true(nikon_community('ownDetail',fresh,p)->>'status'='rejected','rejection persisted');
 PERFORM pg_temp.check_true(jsonb_path_query_first(nikon_community('messages',fresh),'$.items[*] ? (@.type == "review_rejected")')->>'text'='local reason','review message committed');
 FOR i IN 1..4 LOOP PERFORM nikon_community('reserveUpload',fresh); END LOOP;
 caught:=false; BEGIN PERFORM nikon_community('reserveUpload',fresh); EXCEPTION WHEN raise_exception THEN caught:=SQLERRM='UPLOAD_QUOTA'; END; PERFORM pg_temp.check_true(caught,'new account upload quota');
 FOR i IN 1..3 LOOP file:=pg_temp.local_file('normal-'||i); PERFORM nikon_community('addAsset',normal,NULL,jsonb_build_object('asset',file)); PERFORM nikon_community('save',normal,NULL,body||jsonb_build_object('fileAssetId',file->>'id','idempotencyKey','normal-submit-00'||i)); END LOOP;
 file:=pg_temp.local_file('normal-fourth'); PERFORM nikon_community('addAsset',normal,NULL,jsonb_build_object('asset',file)); body:=body||jsonb_build_object('fileAssetId',file->>'id');
 caught:=false; BEGIN PERFORM nikon_community('save',normal,NULL,body||'{"idempotencyKey":"normal-submit-004"}'); EXCEPTION WHEN raise_exception THEN caught:=SQLERRM='SUBMISSION_QUOTA'; END; PERFORM pg_temp.check_true(caught,'ordinary daily three submissions');
 PERFORM nikon_community('adminSetSettings',NULL,NULL,'{"actor":"local-admin","settings":{"dailySubmissions":10}}');
 caught:=false; BEGIN PERFORM nikon_community('save',normal,NULL,body||'{"idempotencyKey":"normal-submit-005"}'); EXCEPTION WHEN raise_exception THEN caught:=SQLERRM='PENDING_QUOTA'; END; PERFORM pg_temp.check_true(caught,'pending cap after configurable daily increase');
 INSERT INTO nikon_presets(id,status,draft,published,published_revision,published_at) VALUES(curated,'published',jsonb_build_object('name','Curated local','file',file),jsonb_build_object('name','Curated local','file',file),1,now());
 PERFORM pg_temp.check_true((nikon_community('feed',NULL,NULL,'{"category":"__uncategorized__"}')->>'total')::integer=1,'uncategorized sentinel and curated feed');
 PERFORM pg_temp.check_true(nikon_community('feed')->'categories' ? '','categories include uncategorized');
 PERFORM pg_temp.check_true(jsonb_array_length(nikon_catalog_manifest()->'presets')=1,'legacy catalog contains curated only');
 PERFORM nikon_community('adminSetSettings',NULL,NULL,'{"actor":"local-admin","settings":{"dailyComments":2,"commentIntervalSeconds":0}}');
 PERFORM nikon_community('comment',commenter,curated,'{"text":"one","idempotencyKey":"comment-budget-001"}');
 PERFORM nikon_community('comment',commenter,curated,'{"text":"two","idempotencyKey":"comment-budget-002"}');
 caught:=false; BEGIN PERFORM nikon_community('comment',commenter,curated,'{"text":"three","idempotencyKey":"comment-budget-003"}'); EXCEPTION WHEN raise_exception THEN caught:=SQLERRM='COMMENT_QUOTA'; END; PERFORM pg_temp.check_true(caught,'daily comments adjusted and enforced');
 PERFORM nikon_community('adminSetSettings',NULL,NULL,'{"actor":"local-admin","settings":{"commentIntervalSeconds":30}}');
 PERFORM nikon_community('comment',fresh,curated,'{"text":"first","idempotencyKey":"comment-fast-001"}');
 caught:=false; BEGIN PERFORM nikon_community('comment',fresh,curated,'{"text":"second","idempotencyKey":"comment-fast-002"}'); EXCEPTION WHEN raise_exception THEN caught:=SQLERRM='COMMENT_TOO_FAST'; END; PERFORM pg_temp.check_true(caught,'30 second interval');
 UPDATE nikon_users SET status='disabled' WHERE id=fresh;
 caught:=false; BEGIN PERFORM nikon_community('readAll',fresh); EXCEPTION WHEN raise_exception THEN caught:=SQLERRM='USER_DISABLED'; END; PERFORM pg_temp.check_true(caught,'disabled user cannot mutate messages');
 PERFORM nikon_community('adminSetRestrictions',NULL,normal,jsonb_build_object('actor','local-admin','submissionBlockedUntil',now()+interval '1 day'));
 caught:=false; BEGIN PERFORM nikon_community('reserveUpload',normal); EXCEPTION WHEN raise_exception THEN caught:=SQLERRM='SUBMISSION_BLOCKED'; END; PERFORM pg_temp.check_true(caught,'submission ban includes uploads');
 caught:=false; BEGIN PERFORM nikon_community('adminSetSettings',NULL,NULL,'{"settings":{"dailyComments":-1}}'); EXCEPTION WHEN raise_exception THEN caught:=SQLERRM='INVALID_COMMUNITY'; END; PERFORM pg_temp.check_true(caught,'invalid quotas rejected');
 INSERT INTO nikon_community_audit(actor,action,target,created_at) VALUES('local','expired-audit','local',now()-interval '100 days');
 UPDATE nikon_abuse_windows SET window_start=now()-interval '2 hours' WHERE key='community:cleanup'; PERFORM nikon_community_cleanup();
 PERFORM pg_temp.check_true(NOT EXISTS(SELECT 1 FROM nikon_community_audit WHERE action='expired-audit'),'bounded cleanup removes expired audit records');
END $$;
DO $$
DECLARE old_user uuid:=gen_random_uuid(); newcomer uuid:=gen_random_uuid(); rejected_user uuid:=gen_random_uuid(); aging_user uuid:=gen_random_uuid();
 preset uuid:=gen_random_uuid(); root_id uuid; pending_root uuid; pending_reply uuid; cancelled uuid; rejected_reply uuid; self_root uuid; aging_reply uuid;
 result jsonb; body jsonb; caught boolean;
BEGIN
 INSERT INTO nikon_users(id,nickname,created_at) VALUES(old_user,'local-old-first',now()-interval '2 days'),(newcomer,'local-new-moderation',now()),
  (rejected_user,'local-unreviewed-author',now()),(aging_user,'local-aging-author',now());
 INSERT INTO nikon_presets(id,status,draft,published,published_revision,published_at) VALUES(preset,'published','{"name":"Review fixture"}','{"name":"Review fixture"}',1,now());
 PERFORM nikon_community('adminSetSettings',NULL,NULL,'{"actor":"local-admin","settings":{"dailyComments":50,"newDayComments":10,"commentIntervalSeconds":0}}');
 result:=nikon_community('comment',old_user,preset,'{"text":"old account direct","idempotencyKey":"old-first-public"}'); root_id:=(result->>'id')::uuid;
 PERFORM pg_temp.check_true(result->>'status'='visible','old account low-risk first comment is directly visible');
 body:='{"text":"pending root secret","idempotencyKey":"new-first-pending"}';
 result:=nikon_community('comment',newcomer,preset,body); pending_root:=(result->>'id')::uuid;
 PERFORM pg_temp.check_true(result->>'status'='pending' AND result->>'text'='','new first comment queued with private body');
 PERFORM pg_temp.check_true(nikon_community('comment',newcomer,preset,body)->>'id'=pending_root::text,'pending creation is idempotent');
 body:=jsonb_build_object('text','pending reply secret','parentId',root_id,'idempotencyKey','new-second-pending');
 result:=nikon_community('comment',newcomer,preset,body); pending_reply:=(result->>'id')::uuid;
 PERFORM pg_temp.check_true(result->>'status'='pending','new account remains moderated until one approved visible comment');
 PERFORM pg_temp.check_true((nikon_community('comments',NULL,preset)->>'total')::integer=1,'pending root omitted from public list');
 PERFORM pg_temp.check_true((nikon_community('replies',NULL,root_id)->>'total')::integer=0,'pending reply omitted from public replies');
 PERFORM pg_temp.check_true(NOT (nikon_community('comments',NULL,preset,jsonb_build_object('focusCommentId',pending_reply))->>'focusAvailable')::boolean,'pending focus cannot reveal author/body');
 PERFORM pg_temp.check_true((nikon_community('unread',old_user)->>'unread')::integer=0,'pending reply sends no notification');
 PERFORM pg_temp.check_true(nikon_community('adminComments',NULL,NULL,'{"status":"pending"}')->'items' @> jsonb_build_array(jsonb_build_object('id',pending_reply)),'moderation pending filter includes queued reply');
 PERFORM nikon_community('adminReviewComment',NULL,pending_reply,'{"actor":"local-admin","decision":"restore","reason":"approved"}');
 PERFORM nikon_community('adminReviewComment',NULL,pending_reply,'{"actor":"local-admin","decision":"restore","reason":"retry"}');
 PERFORM pg_temp.check_true((nikon_community('unread',old_user)->>'unread')::integer=1,'approval creates exactly one durable notification even on retry');
 PERFORM pg_temp.check_true(nikon_community('comment',newcomer,preset,body)->>'text'='pending reply secret','idempotent replay returns current approved status');
 PERFORM pg_temp.check_true((SELECT status='visible' AND was_public FROM nikon_community_comments WHERE id=pending_reply),'approval records public history');
 result:=nikon_community('comment',newcomer,preset,'{"text":"approved account direct","idempotencyKey":"new-after-approval"}'); self_root:=(result->>'id')::uuid;
 PERFORM pg_temp.check_true(result->>'status'='visible','approved new account can post directly');
 PERFORM nikon_community('comment',newcomer,preset,jsonb_build_object('text','self approved reply','parentId',self_root,'idempotencyKey','new-self-public'));
 PERFORM pg_temp.check_true((nikon_community('unread',newcomer)->>'unread')::integer=0,'approved self reply does not notify');
 result:=nikon_community('comment',rejected_user,preset,'{"text":"cancel pending secret","idempotencyKey":"cancel-unreviewed"}'); cancelled:=(result->>'id')::uuid;
 PERFORM nikon_community('deleteComment',rejected_user,cancelled);
 PERFORM pg_temp.check_true((SELECT status='deleted' AND NOT was_public FROM nikon_community_comments WHERE id=cancelled),'cancelled pending retains private history');
 PERFORM pg_temp.check_true(nikon_community('comments',NULL,preset)::text NOT LIKE '%local-unreviewed-author%','cancelled pending author never leaks through deleted placeholder');
 result:=nikon_community('comment',rejected_user,preset,jsonb_build_object('text','reject pending secret','parentId',root_id,'idempotencyKey','reject-unreviewed')); rejected_reply:=(result->>'id')::uuid;
 PERFORM nikon_community('adminReviewComment',NULL,rejected_reply,'{"actor":"local-admin","decision":"hide","reason":"review rejection"}');
 PERFORM pg_temp.check_true((SELECT status='hidden' AND reason='review rejection' AND NOT was_public FROM nikon_community_comments WHERE id=rejected_reply),'pending rejection persists reason without publication');
 PERFORM pg_temp.check_true((nikon_community('unread',old_user)->>'unread')::integer=1,'rejection does not notify target');
 PERFORM nikon_community('adminReviewComment',NULL,rejected_reply,'{"actor":"local-admin","decision":"restore","reason":"review reversed"}');
 PERFORM pg_temp.check_true((nikon_community('unread',old_user)->>'unread')::integer=2,'later approval of rejected pending sends one reply notification');
 result:=nikon_community('comment',aging_user,preset,jsonb_build_object('text','aging pending','parentId',root_id,'idempotencyKey','aging-before-day')); aging_reply:=(result->>'id')::uuid;
 PERFORM pg_temp.check_true(result->>'status'='pending','unapproved account under 24 hours stays pending');
 UPDATE nikon_users SET created_at=now()-interval '2 days' WHERE id=aging_user;
 result:=nikon_community('comment',aging_user,preset,'{"text":"aged direct","idempotencyKey":"aging-after-day"}');
 PERFORM pg_temp.check_true(result->>'status'='visible','ordinary aged account can post directly');
 UPDATE nikon_presets SET status='unpublished' WHERE id=preset;
 caught:=false; BEGIN PERFORM nikon_community('adminReviewComment',NULL,aging_reply,'{"actor":"local-admin","decision":"restore"}'); EXCEPTION WHEN raise_exception THEN caught:=SQLERRM='COMMENT_UNAVAILABLE'; END;
 PERFORM pg_temp.check_true(caught,'approval cannot notify about an unavailable preset');
 PERFORM pg_temp.check_true((SELECT status='pending' FROM nikon_community_comments WHERE id=aging_reply),'failed approval rolls back comment visibility');
END $$;
ROLLBACK;
